TOK=$(cat /tmp/tok)
echo "===== AR REPOS ====="
curl -s -H "Authorization: Bearer $TOK" "https://artifactregistry.googleapis.com/v1/projects/redu-425516/locations/us-central1/repositories" | python3 -c "
import sys,json;d=json.load(sys.stdin)
for r in d.get('repositories',[]): print(r['name'].split('/')[-1],'|',r.get('format'))
"
echo "===== PACKAGES in app-images ====="
curl -s -H "Authorization: Bearer $TOK" "https://artifactregistry.googleapis.com/v1/projects/redu-425516/locations/us-central1/repositories/app-images/packages" | python3 -c "
import sys,json;d=json.load(sys.stdin)
for p in d.get('packages',[]): print(p['name'].split('/')[-1])
"

TOK=$(cat /tmp/tok)
curl -s -H "Authorization: Bearer $TOK" "https://artifactregistry.googleapis.com/v1/projects/redu-425516/locations/us-central1/repositories/app-images/packages/umami/versions?pageSize=50" | python3 -c "
import sys,json;d=json.load(sys.stdin)
for v in d.get('versions',[]):
    print(v['name'].split('/')[-1][:22],'| created',v.get('createTime'),'| tags',[t.split('/')[-1] for t in v.get('relatedTags',[]) if isinstance(t,str)] or [t.get('name','').split('/')[-1] for t in v.get('relatedTags',[])])
"
